<?php
namespace App\Controllers\Admin;
use App\Controllers\BaseController;
class Dashboard extends BaseController { public function index(){ if(session('role')==='admin'){ return redirect()->to('/admin/booking'); } $db=db_connect(); $today=date('Y-m-d'); $month=date('Y-m'); $startWeek=date('Y-m-d', strtotime('monday this week')); $endWeek=date('Y-m-d', strtotime('sunday this week')); $daily=$db->table('transactions')->select('DATE(transaction_date) d, SUM(amount) total')->where('DATE(transaction_date) >=', date('Y-m-01'))->where('DATE(transaction_date) <=', date('Y-m-t'))->groupBy('DATE(transaction_date)')->get()->getResultArray(); $popular=$db->table('bookings b')->select('s.name, COUNT(*) total')->join('services s','s.id=b.service_id')->where('b.status','completed')->like('b.booking_date',$month,'after')->groupBy('s.id')->orderBy('total','DESC')->limit(5)->get()->getResultArray(); $status=$db->table('bookings')->select('status, COUNT(*) total')->groupBy('status')->get()->getResultArray(); return view('admin/dashboard',['today'=>$db->table('transactions')->where('DATE(transaction_date)',$today)->selectSum('amount')->get()->getRowArray()['amount']??0,'week'=>$db->table('transactions')->where('DATE(transaction_date) >=',$startWeek)->where('DATE(transaction_date) <=',$endWeek)->selectSum('amount')->get()->getRowArray()['amount']??0,'month'=>$db->table('transactions')->like('transaction_date',$month,'after')->selectSum('amount')->get()->getRowArray()['amount']??0,'daily'=>$daily,'popular'=>$popular,'status'=>$status]); } }
